// P2-C (2026-10-31): platform-side view of the engine compliance registry.
//
// Single source of truth: sentinel/compliance.py → exported by
// `python -m sentinel.cli compliance --json` → checked in as
// src/lib/compliance-registry.json (regenerated by
// scripts/gen_compliance_registry.py; CI fails on drift).
// The platform NEVER re-derives mappings — it renders what the engine owns.

import registry from "./compliance-registry.json";

export type ComplianceInfo = {
  type: string;
  mapped: boolean;
  cwe: string | null;
  cwe_label: string | null;
  owasp_2021: string | null;
  owasp_2021_title: string | null;
  owasp_2021_src: string | null;
  owasp_2025: string | null;
  owasp_2025_title: string | null;
  owasp_2025_src: string | null;
  pci_dss: string | null;
};

export const PCI_DSS_REQUIREMENT: string = registry.pci_dss.requirement;
export const PCI_DSS_NOTE: string = registry.pci_dss.note;
export const OWASP_2021_CATEGORIES: Record<string, string> = registry.categories.owasp_2021;
export const OWASP_2025_CATEGORIES: Record<string, string> = registry.categories.owasp_2025;
export const CWE_LABELS: Record<string, string> = registry.cwe_labels;
export const COMPLIANCE_TYPES: Record<string, ComplianceInfo> = registry.types;

const UNMAPPED: ComplianceInfo = {
  type: "",
  mapped: false,
  cwe: null,
  cwe_label: null,
  owasp_2021: null,
  owasp_2021_title: null,
  owasp_2021_src: null,
  owasp_2025: null,
  owasp_2025_title: null,
  owasp_2025_src: null,
  pci_dss: null,
};

/** Lookup by engine finding type. Unknown types return the honest unmapped
 * shape (mapped=false) — never a guess, matching the engine contract. */
export function complianceFor(type: string): ComplianceInfo {
  const hit = COMPLIANCE_TYPES[type];
  return hit ?? { ...UNMAPPED, type };
}

/** Parse a stored complianceJson column back to ComplianceInfo. */
export function complianceFromJson(raw: string | null | undefined): ComplianceInfo | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Partial<ComplianceInfo>;
    if (typeof parsed !== "object" || parsed === null) return null;
    return { ...UNMAPPED, ...parsed, type: parsed.type ?? "" };
  } catch {
    return null;
  }
}
